-- Iceland deep-dive ES/DE/FR translations, completing 418 against the
-- English content in migration 418. This is a SEPARATE migration file,
-- so every translation row looks up its parent row via a JOIN on stable
-- identifying columns (country code / section / sort_order), never via
-- (SELECT MAX(id) ...). INSERT OR IGNORE throughout. Iceland has no
-- deep_dive_penalty_rows (no statutory penalty regime), matching 418.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Modelo de recepción B2G sin clearance -- los organismos públicos islandeses están obligados a recibir facturas electrónicas conformes con la norma EN 16931 desde 2019/2020, a través de Fjársýsla ríkisins y la red Peppol; no existe mandato B2B ni ninguno en discusión', 'Esta página de análisis refleja el texto del Reglamento 44/2019 y la orientación pública disponible del gobierno islandés y de OpenPeppol a inicios de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal. Confirme los requisitos vigentes directamente con Fjársýsla ríkisins o con un asesor legal islandés antes de basar en esta página sus decisiones de cumplimiento.', 'El Ministerio de Finanzas y Asuntos Económicos de Islandia emitió el Reglamento 44/2019 el 24 de enero de 2019, transponiendo la Directiva 2014/55/UE de la UE a través de la pertenencia de Islandia al EEE. El requisito se implantó de forma escalonada según el tipo de organismo público: las instituciones estatales desde el 18 de abril de 2019, y después los municipios, empresas públicas y otras entidades que operan bajo derechos especiales o monopolios desde el 18 de abril de 2020, completando así el despliegue. Fjársýsla ríkisins (la Autoridad de Gestión Financiera) es la Peppol Authority registrada de Islandia ante OpenPeppol desde 2020. Nada ha cambiado desde entonces -- no ha habido ningún desarrollo B2B, propuesta de mandato ni anuncio con fecha en Islandia desde que se completó el despliegue del reglamento en 2019-2020.', 'Una factura electrónica conforme cumple con la norma europea EN 16931, implementada a nivel nacional como TS 236:2018 (Staðlaráð Íslands, el organismo islandés de normalización) -- la implementación específica islandesa de Peppol BIS Billing 3.0. No existe ningún formato nacional antiguo independiente que siga siendo obligatorio en paralelo; un PDF simple no se acepta explícitamente como factura electrónica legible por máquina.', 'El reglamento se aplica a los compradores públicos bajo la Ley de Contratación Pública de Islandia, las normas de contratación de servicios públicos (agua/energía/transporte/postal), los contratos de concesión por encima de los umbrales del EEE, y las normas de contratación de defensa/seguridad -- estructurado en torno a los umbrales de valor de contratación de la UE/EEE existentes, en lugar de una única norma fija. Quedan excluidos los contratos confidenciales, los que requieren medidas de seguridad especiales, o los que protegen intereses fundamentales del Estado. No existe ningún alcance B2B en absoluto: Islandia nunca ha promulgado, redactado ni discutido públicamente un mandato de facturación electrónica entre empresas.', 'La mayoría de las empresas que leen esto solo necesitan confirmar que pueden facturar electrónicamente a los organismos públicos islandeses -- no hay ningún plazo B2B próximo para el que prepararse, y no se ha anunciado ninguno.', 'Islandia no tiene un régimen sancionador legal para el incumplimiento de la facturación electrónica -- la propia ficha país de la Comisión Europea lo indica explícitamente, y ninguna fuente independiente en esta ronda de investigación encontró lo contrario.', 'Islandia exige que los organismos públicos reciban facturas electrónicas conformes con la norma EN 16931 desde 2019 (instituciones estatales) y 2020 (municipios y empresas públicas), en virtud del Reglamento 44/2019 -- canalizadas a través de Fjársýsla ríkisins sobre la red Peppol (Peppol BIS Billing 3.0 / TS 236). No existe mandato B2B, ni propuesta B2B, ni régimen sancionador legal -- se trata de un mandato B2G maduro y estable, sin nada que esté cambiando actualmente.', '🇮🇸' FROM countries WHERE code = 'IS';

