INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y red', '[["Norma", "EN 16931, implementada a nivel nacional como TS 236:2018 (Staðlaráð Íslands)"], ["Formato práctico", "Peppol BIS Billing 3.0"], ["Red", "Peppol -- Fjársýsla ríkisins es la Peppol Authority registrada de Islandia desde 2020"], ["Formato antiguo/heredado", "Ninguno requerido en paralelo -- TS 236 es en sí misma la implementación islandesa de Peppol BIS 3.0, no un puente hacia ella"]]', 'Una factura en PDF simple no se considera explícitamente una factura electrónica conforme y legible por máquina bajo este régimen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Envío a instituciones estatales islandesas', '[["Organismo receptor", "Fjársýsla ríkisins (Autoridad de Gestión Financiera), en representación de la mayoría de las instituciones estatales"], ["Vía", "Punto de acceso Peppol, o una opción de envío web dirigida a proveedores para empresas sin integración con un sistema contable"], ["Sin paso de clearance", "Se trata de un mandato de comprador público exclusivamente de recepción, no de un modelo de clearance/aprobación gubernamental -- no existe ningún paso en el que una autoridad tributaria valide la factura antes de que llegue al comprador"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién está cubierto', '[["Instituciones estatales", "Cubiertas desde el 18 de abril de 2019"], ["Municipios, empresas públicas, entidades con derechos especiales/monopolio", "Cubiertas desde el 18 de abril de 2020"], ["Base de contratación", "Ley de Contratación Pública, normas de contratación de servicios públicos, contratos de concesión por encima de los umbrales del EEE, normas de contratación de defensa/seguridad"], ["Excluidos", "Contratos confidenciales, contratos que requieren medidas de seguridad especiales, o contratos que protegen intereses fundamentales del Estado"]]', 'La cobertura se estructura en torno a los umbrales de valor de contratación de la UE/EEE existentes, en lugar de un único umbral monetario fijo -- el régimen contractual aplicable determina si una compra concreta entra en el alcance, y no una cifra única.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Sin mandato B2B', '[["¿Promulgado?", "No"], ["¿Redactado?", "No"], ["¿Discutido públicamente con una fecha?", "No -- la propia ficha país de Islandia de 2025 de la Comisión Europea está autoseñalada como \"SIN VERIFICACIÓN\" y no enumera ningún desarrollo de 2024-2026"]]', 'Un plazo del "1 de julio de 2026" para retirar un formato EDI BII más antiguo en favor de Peppol BIS 3.0 se repite en varios blogs de proveedores -- no se remonta a ninguna fuente primaria islandesa u de OpenPeppol y no se presenta como un hecho en esta página. El propio perfil de país de Islandia de OpenPeppol menciona únicamente que la comunidad EDI islandesa aprobó directrices para migrar de documentos EDIFACT a Peppol BIS, sin indicar ninguna fecha.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '💰 No se encontró ningún régimen sancionador legal', NULL, NULL, 'A diferencia de la mayoría de las jurisdicciones de este rastreador, el marco de facturación electrónica de Islandia no contempla ningún calendario de multas o sanciones específico para el incumplimiento. La propia ficha país de facturación electrónica de la Comisión Europea para Islandia lo indica explícitamente, y ninguna fuente gubernamental islandesa independiente en esta ronda de investigación describió tampoco ninguno.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '📄 La aplicación es procedimental, no económica', NULL, NULL, 'Dado que se trata de un mandato de comprador público exclusivamente de recepción, y no de un régimen de clearance o de reporte, el mecanismo práctico se basa en el proceso de contratación: un organismo público que no pueda recibir una factura electrónica conforme está, en sí mismo, en desacuerdo con el reglamento, y un proveedor que envíe fuera del canal exigido se arriesga a un retraso en el pago o a un rechazo, más que a una multa legal.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Un mandato maduro y estable', NULL, NULL, 'El despliegue del Reglamento 44/2019 se completó en abril de 2020 y nada ha cambiado desde entonces en cuanto a su alcance, formato o aplicación -- no se ha encontrado ninguna enmienda pendiente, consulta o iniciativa de endurecimiento de la aplicación en esta ronda de investigación. Se trata de uno de los mandatos exclusivamente B2G más consolidados de este rastreador.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme si su cliente está cubierto', 'Compruebe si el organismo público islandés al que factura es una institución estatal, un municipio, una empresa pública, o una entidad con derechos especiales o de monopolio -- y si el contrato se rige por la Ley de Contratación Pública, o por las normas de contratación de servicios públicos, concesión, o defensa/seguridad.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su software de facturación pueda generar salidas en Peppol BIS Billing 3.0', 'No se acepta un PDF simple -- confirme que su software contable o de facturación (o un proveedor de punto de acceso Peppol) pueda generar una factura electrónica conforme con EN 16931 / TS 236.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme su vía de punto de acceso Peppol hacia Fjársýsla ríkisins', 'La mayoría de las instituciones estatales islandesas reciben facturas a través de Fjársýsla ríkisins sobre la red Peppol -- confirme que su punto de acceso puede alcanzarla, o utilice la opción de envío web dirigida a proveedores si no dispone de integración con un sistema contable.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'No se sobreprepare para un mandato B2B no anunciado', 'A mediados de 2026, no se ha promulgado, redactado ni fechado ningún mandato de facturación electrónica B2B para Islandia -- trate con cautela las afirmaciones de proveedores sobre un plazo B2B fijo o de retirada de formato futuro, a menos que pueda remontarlas a una fuente primaria del gobierno islandés o de OpenPeppol.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Reglamento 44/2019 -- texto oficial (island.is)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Fjársýsla ríkisins -- recepción de facturas electrónicas para las instituciones estatales islandesas' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 1;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Empfangsmodell im B2G-Bereich ohne Freigabeverfahren -- isländische öffentliche Stellen sind seit 2019/2020 verpflichtet, EN-16931-konforme E-Rechnungen über Fjársýsla ríkisins und das Peppol-Netzwerk zu empfangen; es gibt keine B2B-Pflicht und keine ist in Diskussion', 'Diese Analyseseite spiegelt den Text der Verordnung 44/2019 sowie öffentlich verfügbare Hinweise der isländischen Regierung und von OpenPeppol mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechtsberatung. Bestätigen Sie aktuelle Anforderungen direkt bei Fjársýsla ríkisins oder einem isländischen Rechtsberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Islands Ministerium für Finanzen und Wirtschaftsangelegenheiten erließ am 24. Januar 2019 die Verordnung 44/2019 und setzte damit über Islands EWR-Mitgliedschaft die EU-Richtlinie 2014/55/EU um. Die Pflicht wurde stufenweise nach Art der öffentlichen Stelle eingeführt: staatliche Institutionen ab dem 18. April 2019, danach Gemeinden, öffentliche Unternehmen und andere Einrichtungen mit besonderen Rechten oder Monopolen ab dem 18. April 2020, womit der Rollout abgeschlossen wurde. Fjársýsla ríkisins (die Finanzverwaltungsbehörde) ist seit 2020 Islands bei OpenPeppol registrierte Peppol Authority. Seither hat sich nichts geändert -- es gab in Island seit Abschluss des Rollouts der Verordnung 2019-2020 keine B2B-Entwicklung, keinen Pflichtvorschlag und keine terminierte Ankündigung.', 'Eine konforme E-Rechnung erfüllt den europäischen Standard EN 16931, national umgesetzt als TS 236:2018 (Staðlaráð Íslands, die isländische Normungsstelle) -- Islands konkrete Umsetzung von Peppol BIS Billing 3.0. Es gibt kein separates älteres nationales Format, das parallel weiterhin erforderlich wäre; ein einfaches PDF wird ausdrücklich nicht als maschinenlesbare E-Rechnung akzeptiert.', 'Die Verordnung gilt für öffentliche Auftraggeber nach Islands Gesetz über die öffentliche Auftragsvergabe, die Vergaberegeln für Versorgungsunternehmen (Wasser/Energie/Verkehr/Post), Konzessionsverträge oberhalb der EWR-Schwellenwerte sowie die Vergaberegeln für Verteidigung/Sicherheit -- ausgerichtet an bestehenden EU-/EWR-Auftragswertschwellen statt an einer einzigen pauschalen Regel. Vertrauliche Verträge, solche, die besondere Sicherheitsmaßnahmen erfordern, oder solche, die grundlegende staatliche Interessen schützen, sind ausgenommen. Es gibt überhaupt keinen B2B-Anwendungsbereich: Island hat nie eine B2B-E-Rechnungspflicht erlassen, entworfen oder öffentlich mit Datum diskutiert.', 'Die meisten Unternehmen, die dies lesen, müssen lediglich bestätigen, dass sie isländische öffentliche Stellen elektronisch in Rechnung stellen können -- es gibt keine bevorstehende B2B-Frist, auf die man sich vorbereiten müsste, und keine wurde angekündigt.', 'Island hat kein gesetzliches Bußgeldregime für die Nichteinhaltung der E-Rechnungspflicht -- das eigene Länderblatt der EU-Kommission stellt dies ausdrücklich fest, und keine unabhängige Quelle in dieser Rechercherunde fand etwas anderes.', 'Island verlangt seit 2019 (staatliche Institutionen) und 2020 (Gemeinden und öffentliche Unternehmen) von öffentlichen Stellen den Empfang EN-16931-konformer E-Rechnungen, nach der Verordnung 44/2019 -- geleitet über Fjársýsla ríkisins über das Peppol-Netzwerk (Peppol BIS Billing 3.0 / TS 236). Es gibt keine B2B-Pflicht, keinen B2B-Vorschlag und kein gesetzliches Bußgeldregime -- dies ist eine ausgereifte, stabile, ausschließlich auf B2G beschränkte Pflicht, bei der sich derzeit nichts ändert.', '🇮🇸' FROM countries WHERE code = 'IS';

