INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Seit 2020', 'Fjársýsla ríkisins als Islands OpenPeppol Peppol Authority registriert' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', 'Keine', 'B2B-Pflicht vorgeschlagen, entworfen oder terminiert, Stand Mitte 2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Netzwerk', '[["Standard", "EN 16931, national umgesetzt als TS 236:2018 (Staðlaráð Íslands)"], ["Praktisches Format", "Peppol BIS Billing 3.0"], ["Netzwerk", "Peppol -- Fjársýsla ríkisins ist seit 2020 Islands registrierte Peppol Authority"], ["Älteres/veraltetes Format", "Kein paralleles Format erforderlich -- TS 236 ist selbst Islands Umsetzung von Peppol BIS 3.0, keine Brücke dorthin"]]', 'Eine einfache PDF-Rechnung gilt unter diesem Regime ausdrücklich nicht als konforme, maschinenlesbare E-Rechnung.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Übermittlung an isländische staatliche Institutionen', '[["Empfangende Stelle", "Fjársýsla ríkisins (Finanzverwaltungsbehörde), im Auftrag der meisten staatlichen Institutionen"], ["Weg", "Peppol-Zugangspunkt oder eine lieferantenseitige Web-Einreichungsoption für Unternehmen ohne Buchhaltungssystem-Integration"], ["Kein Freigabeschritt", "Dies ist eine reine Empfangspflicht für öffentliche Auftraggeber, kein staatliches Freigabe-/Genehmigungsmodell -- es gibt keinen Schritt, in dem eine Steuerbehörde die Rechnung validiert, bevor sie den Käufer erreicht"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer erfasst ist', '[["Staatliche Institutionen", "Erfasst seit 18. April 2019"], ["Gemeinden, öffentliche Unternehmen, Einrichtungen mit besonderen Rechten/Monopolen", "Erfasst seit 18. April 2020"], ["Vergabegrundlage", "Gesetz über die öffentliche Auftragsvergabe, Vergaberegeln für Versorgungsunternehmen, Konzessionsverträge oberhalb der EWR-Schwellenwerte, Vergaberegeln für Verteidigung/Sicherheit"], ["Ausgenommen", "Vertrauliche Verträge, Verträge, die besondere Sicherheitsmaßnahmen erfordern, oder Verträge, die grundlegende staatliche Interessen schützen"]]', 'Die Erfassung richtet sich nach bestehenden EU-/EWR-Auftragswertschwellen statt nach einem einzigen pauschalen Geldschwellenwert -- welches Vertragsregime gilt, entscheidet, ob ein bestimmter Einkauf erfasst ist, nicht eine einzelne Zahl.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Keine B2B-Pflicht', '[["Erlassen?", "Nein"], ["Entworfen?", "Nein"], ["Öffentlich mit Datum diskutiert?", "Nein -- das eigene Islandländerblatt 2025 der EU-Kommission ist selbst als \"KEINE VERIFIZIERUNG\" gekennzeichnet und listet keine Entwicklungen für 2024-2026 auf"]]', 'Eine Frist zum "1. Juli 2026" für die Abschaffung eines älteren BII-EDI-Formats zugunsten von Peppol BIS 3.0 wird in mehreren Anbieter-Blogs wiederholt -- sie lässt sich auf keine primäre isländische oder OpenPeppol-Quelle zurückführen und wird auf dieser Seite nicht als Tatsache dargestellt. Das eigene Islandländerprofil von OpenPeppol erwähnt lediglich, dass die isländische EDI-Gemeinschaft Leitlinien für die Migration von EDIFACT-Dokumenten zu Peppol BIS gebilligt hat, ohne ein Datum zu nennen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '💰 Kein gesetzliches Bußgeldregime gefunden', NULL, NULL, 'Anders als in den meisten Jurisdiktionen dieses Trackers sieht Islands E-Rechnungsrahmen keinen eigenen Bußgeld- oder Sanktionskatalog für Nichteinhaltung vor. Das eigene eInvoicing-Länderblatt der EU-Kommission für Island stellt dies ausdrücklich fest, und auch keine unabhängige isländische Regierungsquelle in dieser Rechercherunde beschrieb ein solches.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '📄 Durchsetzung erfolgt verfahrensrechtlich, nicht finanziell', NULL, NULL, 'Da es sich um eine reine Empfangspflicht für öffentliche Auftraggeber und nicht um ein Freigabe- oder Meldesystem handelt, ist der praktische Mechanismus vergabeprozessbasiert: Eine öffentliche Stelle, die keine konforme E-Rechnung empfangen kann, verstößt selbst gegen die Verordnung, und ein Lieferant, der außerhalb des vorgeschriebenen Kanals einreicht, riskiert eine Zahlungsverzögerung oder Ablehnung statt eines gesetzlichen Bußgelds.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Eine ausgereifte, stabile Pflicht', NULL, NULL, 'Der Rollout der Verordnung 44/2019 wurde im April 2020 abgeschlossen, und seither hat sich an Umfang, Format oder Durchsetzung nichts geändert -- in dieser Rechercherunde wurde keine anstehende Änderung, Konsultation oder Initiative zur Verschärfung der Durchsetzung gefunden. Dies ist eine der am stärksten gefestigten, ausschließlich auf B2G beschränkten Pflichten in diesem Tracker.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie, ob Ihr Kunde erfasst ist', 'Prüfen Sie, ob die isländische öffentliche Stelle, der Sie eine Rechnung stellen, eine staatliche Institution, eine Gemeinde, ein öffentliches Unternehmen oder eine Einrichtung mit besonderen Rechten/Monopolstellung ist -- und ob der Vertrag unter das Gesetz über die öffentliche Auftragsvergabe oder die Vergaberegeln für Versorgungsunternehmen, Konzessionen oder Verteidigung/Sicherheit fällt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Ihre Rechnungssoftware Peppol-BIS-Billing-3.0-Ausgaben erzeugen kann', 'Ein einfaches PDF wird nicht akzeptiert -- bestätigen Sie, dass Ihre Buchhaltungs- oder Rechnungssoftware (oder ein Peppol-Zugangspunkt-Anbieter) eine konforme EN-16931-/TS-236-E-Rechnung erzeugen kann.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie Ihren Peppol-Zugangspunktweg zu Fjársýsla ríkisins', 'Die meisten isländischen staatlichen Institutionen empfangen Rechnungen über Fjársýsla ríkisins über das Peppol-Netzwerk -- bestätigen Sie, dass Ihr Zugangspunkt diese erreichen kann, oder nutzen Sie die lieferantenseitige Web-Einreichungsoption, falls Sie keine Buchhaltungssystem-Integration haben.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bereiten Sie sich nicht übermäßig auf eine nicht angekündigte B2B-Pflicht vor', 'Für Island wurde Stand Mitte 2026 keine B2B-E-Rechnungspflicht erlassen, entworfen oder terminiert -- behandeln Sie Anbieterbehauptungen über eine feste künftige B2B- oder Formatabschaffungsfrist mit Vorsicht, sofern Sie diese nicht auf eine primäre isländische Regierungs- oder OpenPeppol-Quelle zurückführen können.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Verordnung 44/2019 -- offizieller Text (island.is)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Fjársýsla ríkisins -- Empfang von E-Rechnungen für isländische staatliche Institutionen' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 1;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Modèle de réception B2G sans dédouanement -- les organismes publics islandais sont tenus de recevoir des factures électroniques conformes à la norme EN 16931 depuis 2019/2020, via Fjársýsla ríkisins et le réseau Peppol ; il n''existe aucune obligation B2B, et aucune n''est en discussion', 'Cette page d''analyse reflète le texte du règlement 44/2019 ainsi que les indications publiques disponibles du gouvernement islandais et d''OpenPeppol début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique. Confirmez les exigences actuelles directement auprès de Fjársýsla ríkisins ou d''un conseiller juridique islandais avant de fonder vos décisions de conformité sur cette page.', 'Le ministère islandais des Finances et des Affaires économiques a émis le règlement 44/2019 le 24 janvier 2019, transposant la directive 2014/55/UE de l''UE via l''appartenance de l''Islande à l''EEE. L''exigence a été introduite progressivement selon le type d''organisme public : les institutions étatiques à partir du 18 avril 2019, puis les municipalités, les entreprises publiques et les autres entités exerçant des droits spéciaux ou des monopoles à partir du 18 avril 2020, achevant ainsi le déploiement. Fjársýsla ríkisins (l''Autorité de gestion financière) est la Peppol Authority enregistrée de l''Islande auprès d''OpenPeppol depuis 2020. Rien n''a changé depuis -- aucun développement B2B, aucune proposition d''obligation, ni aucune annonce datée n''a eu lieu en Islande depuis l''achèvement du déploiement du règlement en 2019-2020.', 'Une facture électronique conforme respecte la norme européenne EN 16931, mise en œuvre au niveau national sous la forme de la TS 236:2018 (Staðlaráð Íslands, l''organisme islandais de normalisation) -- la mise en œuvre spécifique de l''Islande de Peppol BIS Billing 3.0. Il n''existe pas de format national ancien distinct encore exigé en parallèle ; un simple PDF n''est explicitement pas accepté comme facture électronique lisible par machine.', 'Le règlement s''applique aux acheteurs publics relevant de la loi islandaise sur les marchés publics, des règles de passation de marchés des services publics (eau/énergie/transport/postal), des contrats de concession dépassant les seuils de l''EEE, et des règles de passation de marchés de défense/sécurité -- articulé autour des seuils de valeur des marchés UE/EEE existants plutôt qu''autour d''une règle unique et uniforme. Les contrats confidentiels, ceux nécessitant des mesures de sécurité spéciales, ou ceux protégeant des intérêts fondamentaux de l''État, sont exclus. Il n''existe aucun champ d''application B2B : l''Islande n''a jamais adopté, rédigé, ni discuté publiquement d''une obligation de facturation électronique entre entreprises.', 'La plupart des entreprises qui lisent cette page n''ont besoin que de confirmer qu''elles peuvent facturer électroniquement les organismes publics islandais -- il n''y a aucune échéance B2B à venir à laquelle se préparer, et aucune n''a été annoncée.', 'L''Islande ne dispose d''aucun régime de sanctions légal en cas de non-conformité en matière de facturation électronique -- la fiche pays de la Commission européenne elle-même le précise explicitement, et aucune source indépendante n''a démontré le contraire au cours de cette phase de recherche.', 'L''Islande exige que les organismes publics reçoivent des factures électroniques conformes à la norme EN 16931 depuis 2019 (institutions étatiques) et 2020 (municipalités et entreprises publiques), en vertu du règlement 44/2019 -- acheminées via Fjársýsla ríkisins sur le réseau Peppol (Peppol BIS Billing 3.0 / TS 236). Il n''existe aucune obligation B2B, aucune proposition B2B, et aucun régime de sanctions légal -- il s''agit d''une obligation mature, stable, exclusivement B2G, sans évolution en cours actuellement.', '🇮🇸' FROM countries WHERE code = 'IS';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '24 janv. 2019', 'Le règlement 44/2019 est publié au journal officiel' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '18 avr. 2020', 'Déploiement complet dans le secteur public achevé (municipalités et entreprises publiques)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Depuis 2020', 'Fjársýsla ríkisins enregistrée comme Peppol Authority de l''Islande auprès d''OpenPeppol' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', 'Aucune', 'Obligation B2B proposée, rédigée ou datée à la mi-2026' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'IS' AND s.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et réseau', '[["Norme", "EN 16931, mise en œuvre au niveau national sous la forme de la TS 236:2018 (Staðlaráð Íslands)"], ["Format pratique", "Peppol BIS Billing 3.0"], ["Réseau", "Peppol -- Fjársýsla ríkisins est la Peppol Authority enregistrée de l''Islande depuis 2020"], ["Format ancien/hérité", "Aucun format requis en parallèle -- la TS 236 constitue elle-même la mise en œuvre islandaise de Peppol BIS 3.0, et non une passerelle vers celle-ci"]]', 'Une simple facture PDF n''est explicitement pas considérée comme une facture électronique conforme et lisible par machine dans le cadre de ce régime.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Soumission aux institutions étatiques islandaises', '[["Organisme récepteur", "Fjársýsla ríkisins (Autorité de gestion financière), pour le compte de la plupart des institutions étatiques"], ["Voie", "Point d''accès Peppol, ou une option de soumission web destinée aux fournisseurs pour les entreprises sans intégration à un système comptable"], ["Aucune étape de dédouanement", "Il s''agit d''une obligation de réception uniquement pour l''acheteur public, et non d''un modèle de dédouanement/approbation gouvernemental -- il n''existe aucune étape où une autorité fiscale valide la facture avant qu''elle n''atteigne l''acheteur"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui est couvert', '[["Institutions étatiques", "Couvertes depuis le 18 avril 2019"], ["Municipalités, entreprises publiques, entités à droits spéciaux/monopoles", "Couvertes depuis le 18 avril 2020"], ["Base de passation de marché", "Loi sur les marchés publics, règles de passation de marchés des services publics, contrats de concession dépassant les seuils de l''EEE, règles de passation de marchés de défense/sécurité"], ["Exclus", "Contrats confidentiels, contrats nécessitant des mesures de sécurité spéciales, ou contrats protégeant des intérêts fondamentaux de l''État"]]', 'La couverture est structurée autour des seuils de valeur des marchés UE/EEE existants plutôt qu''autour d''un seuil monétaire unique et fixe -- c''est le régime contractuel applicable qui détermine si un achat donné entre dans le champ d''application, et non un chiffre unique.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Aucune obligation B2B', '[["Adoptée ?", "Non"], ["Rédigée ?", "Non"], ["Discutée publiquement avec une date ?", "Non -- la fiche pays 2025 de l''Islande de la Commission européenne elle-même est signalée comme \"AUCUNE VÉRIFICATION\" et ne recense aucune évolution pour 2024-2026"]]', 'Une échéance du « 1er juillet 2026 » pour le retrait d''un ancien format EDI BII au profit de Peppol BIS 3.0 est reprise sur plusieurs blogs de fournisseurs -- elle ne peut être rattachée à aucune source primaire islandaise ou d''OpenPeppol et n''est pas présentée comme un fait sur cette page. Le propre profil pays de l''Islande d''OpenPeppol mentionne seulement que la communauté EDI islandaise a approuvé des lignes directrices pour migrer des documents EDIFACT vers Peppol BIS, sans indiquer de date.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '💰 Aucun régime de sanctions légal identifié', NULL, NULL, 'Contrairement à la plupart des juridictions de ce suivi, le cadre de facturation électronique de l''Islande ne prévoit aucun barème d''amendes ou de sanctions spécifique en cas de non-conformité. La fiche pays eInvoicing de la Commission européenne pour l''Islande le précise explicitement, et aucune source gouvernementale islandaise indépendante n''en a décrit un non plus au cours de cette phase de recherche.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '📄 L''application est procédurale, non financière', NULL, NULL, 'Comme il s''agit d''une obligation de réception uniquement pour l''acheteur public, plutôt que d''un régime de dédouanement ou de déclaration, le mécanisme pratique repose sur le processus de passation de marché : un organisme public incapable de recevoir une facture électronique conforme se trouve lui-même en décalage avec le règlement, et un fournisseur qui soumet en dehors du canal requis risque un retard de paiement ou un rejet plutôt qu''une amende légale.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Une obligation mature et stable', NULL, NULL, 'Le déploiement du règlement 44/2019 s''est achevé en avril 2020, et rien n''a changé depuis dans son champ d''application, son format ou son application -- aucune modification en attente, consultation, ou initiative de renforcement de l''application n''a été trouvée au cours de cette phase de recherche. Il s''agit de l''une des obligations exclusivement B2G les plus stabilisées de ce suivi.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'IS' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez si votre client est couvert', 'Vérifiez si l''organisme public islandais que vous facturez est une institution étatique, une municipalité, une entreprise publique, ou une entité à droits spéciaux/monopole -- et si le contrat relève de la loi sur les marchés publics, ou des règles de passation de marchés des services publics, de concession, ou de défense/sécurité.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre logiciel de facturation peut produire des documents au format Peppol BIS Billing 3.0', 'Un simple PDF n''est pas accepté -- vérifiez que votre logiciel comptable ou de facturation (ou un prestataire de point d''accès Peppol) peut générer une facture électronique conforme à EN 16931 / TS 236.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez votre voie d''accès Peppol vers Fjársýsla ríkisins', 'La plupart des institutions étatiques islandaises reçoivent leurs factures via Fjársýsla ríkisins sur le réseau Peppol -- vérifiez que votre point d''accès peut l''atteindre, ou utilisez l''option de soumission web destinée aux fournisseurs si vous ne disposez pas d''une intégration à un système comptable.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Ne vous préparez pas excessivement à une obligation B2B non annoncée', 'Aucune obligation de facturation électronique B2B n''a été adoptée, rédigée ou datée pour l''Islande à la mi-2026 -- traitez avec prudence les affirmations de fournisseurs concernant une échéance B2B fixe ou de retrait de format à venir, à moins de pouvoir les rattacher à une source primaire du gouvernement islandais ou d''OpenPeppol.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'IS' AND sp.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Règlement 44/2019 -- texte officiel (island.is)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Fjársýsla ríkisins -- réception des factures électroniques pour les institutions étatiques islandaises' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'IS' AND pt.sort_order = 1;
